import UserPage from 'flarum/forum/components/UserPage';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import useStyles from '../styles';
import { call, t } from '../util';
import Album, { isOwnAlbum } from './Album';

/** Profile → Stickers: a member's album, and their spares to ask for. */
export default class UserStickersPage extends UserPage {
  /** The member whose album is loaded. */

  oninit(vnode) {
    super.oninit(vnode);
    useStyles();
    this.album = null;
    this.loadUser(m.route.param('username'));
    this.onChange = () => this.user && this.loadAlbum(this.user);
    window.addEventListener('sticker-book:changed', this.onChange);
  }
  onremove(vnode) {
    super.onremove(vnode);
    window.removeEventListener('sticker-book:changed', this.onChange);
  }
  show(user) {
    super.show(user);
    if (this.shownFor === user.id()) return;
    this.shownFor = user.id();
    this.loadAlbum(user);
  }

  /** The member's album from our endpoint (an empty one if it can't be had). */
  loadAlbum(user) {
    call('GET', '/album', {
      user: user.slug()
    }, {
      quiet: true
    }).then(album => this.album = album).catch(() => this.album = {
      user: null,
      sets: [],
      stats: {}
    }).finally(() => m.redraw());
  }
  content() {
    if (!this.album) return m(LoadingIndicator, {
      display: "block"
    });
    const stats = this.album.stats;
    return m("div", {
      className: "StickerUserPage"
    }, stats?.total ? m("p", {
      className: "StickerUserPage-summary"
    }, t('profile.summary', {
      count: stats.unique,
      total: stats.total,
      sets: stats.completed
    })) : null, m(Album, {
      album: this.album,
      own: isOwnAlbum(this.album)
    }));
  }
}
flarum.reg.add('ernestdefoe-sticker-book', 'forum/components/UserStickersPage', UserStickersPage);