import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import Avatar from 'flarum/common/components/Avatar';
import username from 'flarum/common/helpers/username';
import { call, pushUsers, rarityName, t, user } from '../util';
import { openTrade } from './TradeModal';
export function openSticker(attrs) {
  app.modal.show(StickerModal, attrs);
}

/**
 * One sticker, big. On your own album: offer a spare, or find members who
 * have one to spare. On someone else's: ask them for their spare.
 */
export default class StickerModal extends Modal {
  /** [user id, spares] of members with one to spare, once looked up. */

  oninit(vnode) {
    super.oninit(vnode);
    this.spares = null;
  }
  className() {
    return 'StickerModal Modal--small';
  }
  title() {
    return this.attrs.sticker.name;
  }
  content() {
    const {
      sticker: s,
      album,
      own
    } = this.attrs;
    const me = app.session.user;
    const canTrade = me && app.forum.attribute('stickerCanTrade');
    const owner = album.user;
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: `StickerModal-art StickerModal-art--r${s.rarity} ${s.count ? '' : 'is-missing'}`
    }, m("img", {
      src: s.count ? s.full : s.sil,
      alt: ""
    })), m("p", {
      className: "StickerModal-meta"
    }, m("span", {
      className: `StickerPill StickerPill--r${s.rarity}`
    }, rarityName(s.rarity)), m("span", {
      className: "StickerModal-have"
    }, s.count ? own ? t('sticker.you_have', {
      count: s.count,
      spares: s.count - 1
    }) : t('sticker.they_have', {
      name: owner?.displayName,
      count: s.count
    }) : own ? t('sticker.you_need') : t('sticker.they_need', {
      name: owner?.displayName
    }))), canTrade ? m("div", {
      className: "StickerModal-actions"
    }, this.actions(s, !!own, owner)) : null);
  }
  actions(s, own, owner) {
    if (own && s.count > 1) {
      return m(Button, {
        className: "Button Button--primary Button--block",
        icon: "fas fa-right-left",
        onclick: () => this.trade({
          give: [[s.id, 1]]
        })
      }, t('sticker.offer_spare'));
    }
    if (!own && s.count > 1 && owner) {
      return m(Button, {
        className: "Button Button--primary Button--block",
        icon: "fas fa-hand-holding-heart",
        onclick: () => this.trade({
          to: owner,
          take: [[s.id, 1]]
        })
      }, t('sticker.ask', {
        name: owner.displayName
      }));
    }
    if (own && !s.count) return this.spareFinder(s);
    return null;
  }

  /** For a sticker the member is missing: find who has one to spare, then propose a trade. */
  spareFinder(s) {
    if (this.spares === null) {
      return m(Button, {
        className: "Button Button--block",
        icon: "fas fa-magnifying-glass",
        loading: this.loading,
        onclick: () => this.findSpares(s)
      }, t('sticker.find_spare'));
    }
    if (!this.spares.length) return m("p", {
      className: "StickerModal-none"
    }, t('sticker.no_spares'));
    return m("div", {
      className: "StickerSpares"
    }, m("h4", null, t('sticker.spares_title')), m("ul", null, this.spares.map(([id, n]) => {
      const u = user(id);
      const row = {
        id,
        displayName: u?.displayName(),
        slug: u?.slug()
      };
      return m("li", null, m("span", {
        className: "StickerSpares-who"
      }, m(Avatar, {
        user: u
      }), " ", username(u), " ", m("span", {
        className: "StickerSpares-n"
      }, t('sticker.spare_count', {
        count: n
      }))), m(Button, {
        className: "Button Button--primary",
        onclick: () => this.trade({
          to: row,
          take: [[s.id, 1]]
        })
      }, t('sticker.propose')));
    })));
  }
  findSpares(s) {
    this.loading = true;
    call('GET', '/spares', {
      sticker: s.id
    }).then(data => {
      pushUsers(data.users);
      this.spares = data.spares;
    }).catch(() => {
      /* call() already showed the error */
    }).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
  trade(attrs) {
    // Replace this window with the trade form.
    openTrade(attrs);
  }
}
flarum.reg.add('ernestdefoe-sticker-book', 'forum/components/StickerModal', StickerModal);